css:
&.slide.tpl {
& { padding:84px 100px 80px; display:grid; grid-template-columns:minmax(0,560px) minmax(0,1fr); gap:80px; align-items:stretch; }
.bf-image { margin:0; min-height:0; display:flex; align-items:center; justify-content:center; }
.bf-image img { display:block; max-width:100%; max-height:100%; object-fit:contain; border-radius:calc(var(--radius) * .75); box-shadow:0 30px 80px -30px rgba(0,0,0,.65),0 0 0 1px var(--line); }
.bf-content { display:flex; flex-direction:column; gap:30px; min-width:0; justify-content:center; }
header p { display:inline-block; color:var(--accent); font:600 20px/1 var(--font-mono,var(--mono)); letter-spacing:.14em; text-transform:uppercase; margin:0 0 20px; }
header h2 { font-size:64px; line-height:1.06; margin:0; text-wrap:balance; hyphens:none; overflow-wrap:normal; }
header div { font-size:29px; line-height:1.36; color:var(--muted); margin-top:20px; max-width:44ch; }
header :empty { display:none; }
ol { display:flex; flex-direction:column; gap:14px; list-style:none; padding:0; margin:0; counter-reset:bf; }
li { counter-increment:bf; position:relative; display:grid; grid-template-columns:56px minmax(0,1fr); column-gap:22px; padding:20px 26px 20px 20px; border-radius:calc(var(--radius) * .6); border:1px solid transparent; opacity:1!important; transform:none!important; transition:background .3s ease,border-color .3s ease,opacity .3s ease; }
li::before { content:counter(bf,decimal-leading-zero); grid-row:1 / span 2; align-self:start; font:600 22px/1 var(--font-mono,var(--mono)); color:var(--muted); padding-top:9px; }
li b { display:block; font-size:34px; line-height:1.15; font-weight:650; color:var(--ink); }
li span { display:block; font-size:27px; line-height:1.34; margin-top:8px; color:var(--ink); opacity:0; transition:opacity .3s ease; }
li.in span,li:not([data-step]) span { opacity:1; }
li.step-current { background:color-mix(in srgb,var(--accent) 9%,var(--surface)); border-color:color-mix(in srgb,var(--accent) 60%,transparent); }
li.step-current::before { color:var(--accent); }
li.step-current b { color:var(--accent); }
li.step-past { opacity:.62!important; }
&:has([data-template-end].in),&:has([data-template-end]:not([data-step])) { li { background:transparent; border-color:transparent; opacity:1!important; } li b { color:var(--ink); } li::before { color:var(--accent); } li span { opacity:1; } }
[data-template-end] { position:absolute; width:0; height:0; overflow:hidden; }
&:has(.bf-image img[src=""]) { grid-template-columns:minmax(0,1fr); } &:has(.bf-image img[src=""]) .bf-image { display:none; } &:has(.bf-image img[src=""]) header div { max-width:60ch; }
&:has(li:nth-child(4)) { li { padding-top:14px; padding-bottom:14px; } li b { font-size:31px; } li span { font-size:25px; } }
&[data-body-motion="none"] * { transition:none!important; }
}
